    /// <summary>
    /// Read the transport type for this agent.
    /// This relies on the naming scheme being <c>sse:${sessionId}</c>,
    /// <c>streamable-http:${sessionId}</c>, or <c>rpc:${sessionId}</c>.
    /// </summary>
    abstract getTransportType: unit -> BaseTransportType
    /// <summary>
    /// Read the sessionId for this agent.
    /// This relies on the naming scheme being <c>sse:${sessionId}</c>
    /// or <c>streamable-http:${sessionId}</c>.
    /// </summary>
    abstract getSessionId: unit -> string
    /// <summary>
    /// Get the unique WebSocket. SSE transport only.
    /// </summary>
    abstract getWebSocket: unit -> McpAgent.ShouldSendProtocolMessages.Connection<obj> option
    /// <summary>
    /// Returns options for configuring the RPC server transport.
    /// Override this method to customize RPC transport behavior (e.g., timeout).
    /// </summary>
    /// <example>
    /// <code>
    /// ```typescript
    /// class MyMCP extends McpAgent {
    ///   protected getRpcTransportOptions() {
    ///     return { timeout: 120000 }; // 2 minutes
    ///   }
    /// }
    /// </code>
    /// <code>
