    abstract getRpcTransportOptions: unit -> RPCServerTransportOptions
    /// <summary>
    /// Returns the EventStore for SSE resumability. Defaults to a
    /// DurableObjectEventStore backed by this agent's storage,
    /// letting clients reconnect with <c>Last-Event-ID</c> after the Cloudflare
    /// edge closes an idle SSE stream (~5 minute watchdog) instead of
    /// relying on a server-side keepalive that would block hibernation.
    /// <br /><br />
