    /// </summary>
    abstract getEventStore: unit -> obj option
    /// <summary>
    /// Update and store the props
    /// </summary>
    abstract updateProps: ?props: 'Props -> JS.Promise<unit>
    abstract reinitializeServer: unit -> JS.Promise<unit>
    /// <summary>
    /// Sets up the MCP transport and server every time the Agent is started.
    /// </summary>
    abstract onStart: ?props: 'Props -> JS.Promise<unit>
    /// <summary>
    /// Validates new WebSocket connections.
    /// </summary>
    abstract onConnect: conn: McpAgent.ShouldSendProtocolMessages.Connection<obj> * __1: McpAgent.ShouldSendProtocolMessages.Ctx -> JS.Promise<unit>
    /// <summary>
    /// Handles MCP Messages for the legacy SSE transport.
    /// </summary>
    abstract onSSEMcpMessage: _sessionId: string * messageBody: obj * ?extraInfo: obj -> JS.Promise<exn option>
    /// <summary>
